pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post;

    // Penalty for creating "dead space" (residuals < 10 are often unusable for incoming items)
    // We scale this penalty by the progress; as we near the end of the stream, 
    // we are more desperate to pack tightly.
    if post < 10.0 {
        score -= (10.0 - post) * 5.0 * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, avoid bins that leave very little space
    // that won't be usable, but don't over-penalize early in the stream.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post > 0.0 && post < next_f {
            score += (next_f - post) * 2.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening a new bin (bin_residual == bin_capacity):
    // Only open a new bin if the current fitting bins are extremely poor fits.
    if bin_residual == bin_capacity {
        // If we have many fitting bins, don't open a new one.
        // If we are late in the stream, favor existing bins over new ones.
        score = 25.0 + (fitting_bins_count as f64 * 10.0) + (progress * 50.0);
    } else {
        // Reward bins that keep the mean residual balanced to avoid fragmentation
        let residual_diff = (post - mean_residual).abs();
        score += residual_diff * 0.5;
    }

    score
}

