pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "dead zones": if post_residual is too small to fit typical items, 
    // it effectively wastes space. We penalize small residuals more heavily as the stream progresses.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we increase the score (penalty).
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Global optimization: discourage opening new bins unless necessary (fitting_bins_count == 0).
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy progress-based threshold.
    if bin_residual == bin_capacity {
        // As the stream progresses, the cost of opening a new bin should be balanced against 
        // the mean residual of existing bins to prevent fragmentation.
        score += 45.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Reward bins that bring the bin residual closer to the global mean, 
        // promoting uniform packing density.
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Prefer using bins that are the "last chance" (only one bin fits) to preserve flexibility.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}
